'use strict';
const ApiBuilder = require('claudia-api-builder');
const api = new ApiBuilder();
api.get('/resources/{id}', async (request) => {
  if (!request.pathParams.id) return {statusCode:400,body:{error:'id_required'}};
  return {id:request.pathParams.id};
});
api.post('/resources', async (request) => {
  const body=request.body;
  if (!body || typeof body.name !== 'string' || !body.name.trim()) return {statusCode:400,body:{error:'name_required'}};
  return {statusCode:201,body:{name:body.name.trim()}};
});
module.exports = api;

'use strict';
// Runs the actual Claudia API Builder proxyRouter locally with an API Gateway-shaped request.
// The response body is inspected only for its byte length and is never emitted.
const api = require('./api');
const request = {
  requestContext: {resourcePath: '/resources/{id}', httpMethod: 'GET'},
  pathParameters: {id: process.env.PREVIEW_RESOURCE_ID || 'preview'},
  headers: {},
};
api.proxyRouter(request, {}).then((response) => {
  const body = typeof response.body === 'string' ? response.body : JSON.stringify(response.body ?? null);
  console.log(JSON.stringify({ok: response.statusCode === 200, status: 'route_invoked', response_bytes: Buffer.byteLength(body)}));
  if (response.statusCode !== 200) process.exitCode = 2;
}).catch(() => {
  console.log(JSON.stringify({ok: false, status: 'blocked', diagnostic_codes: ['api_builder_route_failed']}));
  process.exitCode = 2;
});

import api from './api.js';

// Invoke the actual pinned API Builder router. No AWS credentials or network.
export async function preview({configuration}) {
  if(configuration?.language!=='javascript')
    return {ok:false,status:'blocked',diagnostic_codes:['configuration_invalid']};
  const request={requestContext:{resourcePath:'/resources/{id}',httpMethod:'GET'},
    pathParameters:{id:'private-preview'},headers:{}};
  const response=await api.proxyRouter(request,{});
  const ok=response.statusCode===200;
  return {ok,status:ok?'complete':'blocked',route_count:1,verification_count:1,
    diagnostic_codes:['local_fixture_only']};
}
